/// cdecl `(out*) -> AL`, shadowed on a snapshot of the 0x20-byte out structure.
extern "C" fn select_entry(out: usize) -> u32 {
    unsafe {
        let Some((n, orig)) = shadowing(SELECT) else { return tod_select(out) };
        let mut keep = [0u32; 8];
        std::ptr::copy_nonoverlapping(out as *const u32, keep.as_mut_ptr(), 8);
        let ra = call_regs(orig, 0, 0, 0, 0, 0, &[out as u32]);
        let mut theirs = [0u32; 8];
        std::ptr::copy_nonoverlapping(out as *const u32, theirs.as_mut_ptr(), 8);
        std::ptr::copy_nonoverlapping(keep.as_ptr(), out as *mut u32, 8);
        let rr = tod_select(out);
        let mut ours = [0u32; 8];
        std::ptr::copy_nonoverlapping(out as *const u32, ours.as_mut_ptr(), 8);
        if ours != theirs || rr != ra {
            mismatch(SELECT, n, format!("original {ra:#x} {theirs:x?}, Rust {rr:#x} {ours:x?}"));
            std::ptr::copy_nonoverlapping(theirs.as_ptr(), out as *mut u32, 8);
            return ra;
        }
        rr
    }
}

extern "C" fn weather_update_entry() {
    count(UPDATE);
    unsafe { weather_update() }
}

/// Run a blender (`f` computes into the `regions` of `(address, length)` it writes): while shadowed
/// the original copy runs first on the real memory, the Rust result is compared with it and the
/// original's kept on a mismatch.
unsafe fn shadowed_blend(id: usize, p: &Pushad, arg0: u32, regions: &[(usize, usize)], f: impl Fn()) {
    unsafe {
        let Some((n, orig)) = shadowing(id) else {
            f();
            return;
        };
        let mut keep = [[0u8; 128]; 3];
        let mut theirs = [[0u8; 128]; 3];
        let mut ours = [[0u8; 128]; 3];
        let n_r = regions.len().min(3);
        let take = |dst: &mut [[u8; 128]; 3]| {
            for (i, &(a, l)) in regions.iter().take(n_r).enumerate() {
                std::ptr::copy_nonoverlapping(a as *const u8, dst[i].as_mut_ptr(), l.min(128));
            }
        };
        take(&mut keep);
        call_regs(orig, p.eax, p.ecx, p.edx, p.esi, p.edi, &[arg0]);
        take(&mut theirs);
        for (i, &(a, l)) in regions.iter().take(n_r).enumerate() {
            std::ptr::copy_nonoverlapping(keep[i].as_ptr(), a as *mut u8, l.min(128));
        }
        f();
        take(&mut ours);
        if ours != theirs {
            mismatch(id, n, format!("regions {regions:x?}: original and Rust outputs differ"));
            for (i, &(a, l)) in regions.iter().take(n_r).enumerate() {
                std::ptr::copy_nonoverlapping(theirs[i].as_ptr(), a as *mut u8, l.min(128));
            }
        }
    }
}

macro_rules! blender {
    ($entry:ident, $thunk:ident, $id:expr, $blks:ident, $copy:expr, $d:ident, $o:ident) => {
        extern "C" fn $entry(r: &mut Pushad, args: *const u32) {
            unsafe {
                let p = *r;
                let arg = *args;
                let d = p.$d as usize;
                let out = $o(&p, arg) as usize;
                shadowed_blend($id, &p, arg, &[(out, $copy * 4)], || blend(&$blks, d, out, $copy));
            }
        }
        regs_thunk!($thunk, $entry);
    };
}

fn out_ecx(p: &Pushad, _: u32) -> u32 {
    p.ecx
}
fn out_edi(p: &Pushad, _: u32) -> u32 {
    p.edi
}
fn out_arg(_: &Pushad, a: u32) -> u32 {
    a
}

blender!(df0c0_entry, df0c0_thunk, B_FIRST, B_DF0C0, 30, eax, out_ecx);
blender!(e0470_entry, e0470_thunk, B_FIRST + 1, B_E0470, 12, eax, out_ecx);
blender!(e0ca0_entry, e0ca0_thunk, B_FIRST + 2, B_E0CA0, 1, esi, out_edi);
blender!(e0d70_entry, e0d70_thunk, B_FIRST + 3, B_E0D70, 6, esi, out_edi);
blender!(e19e0_entry, e19e0_thunk, B_FIRST + 4, B_E19E0, 14, eax, out_ecx);
blender!(e2380_entry, e2380_thunk, B_FIRST + 5, B_E2380, 7, eax, out_arg);
blender!(e2860_entry, e2860_thunk, B_FIRST + 6, B_E2860, 3, esi, out_arg);
blender!(e2aa0_entry, e2aa0_thunk, B_FIRST + 7, B_E2AA0, 4, esi, out_edi);


// The blenders that write several places (in place over their default records, or into more
// than one structure): each group is (blocks, default, out).

const B_E3880_A: [Blk; 1] = [Blk { v3: false, foff: 0x1b4, mask: 0x01, voff: 0x17c, doff: 0, out: 0 }];
const B_E3880_B: [Blk; 1] = [Blk { v3: false, foff: 0x1b4, mask: 0x10, voff: 0x19c, doff: 0, out: 0 }];
const B_E3A10_A: [Blk; 1] = [Blk { v3: false, foff: 0x1b3, mask: 0x80, voff: 0x178, doff: 0, out: 0 }];
const B_E3A10_B: [Blk; 1] = [Blk { v3: false, foff: 0x1b4, mask: 0x08, voff: 0x198, doff: 0, out: 0 }];
const B_E3230_A: [Blk; 1] = [Blk { v3: true, foff: 0x1b4, mask: 0x02, voff: 0x180, doff: 0, out: 0 }];
const B_E3230_B: [Blk; 1] = [Blk { v3: true, foff: 0x1b4, mask: 0x04, voff: 0x18c, doff: 0, out: 0 }];
const B_E3230_C: [Blk; 1] = [Blk { v3: true, foff: 0x1b4, mask: 0x20, voff: 0x1a0, doff: 0, out: 0 }];
const B_E2D80_A: [Blk; 1] = [Blk { v3: true, foff: 0x1b1, mask: 0x08, voff: 0x30, doff: 0, out: 0 }];
const B_E2D80_B: [Blk; 1] = [Blk { v3: true, foff: 0x1b1, mask: 0x10, voff: 0x3c, doff: 0, out: 0xc }];

unsafe fn select_ok(sel: &mut [u32; 8]) -> bool {
    unsafe { tod_select(sel.as_mut_ptr() as usize) as u8 != 0 }
}

/// 0x4E3880: ESI = default float (blended in place), arg0 = a second float (in place).
extern "C" fn e3880_entry(r: &mut Pushad, args: *const u32) {
    unsafe {
        let p = *r;
        let a0 = *args;
        shadowed_blend(B_FIRST + 8 + 2, &p, a0, &[(p.esi as usize, 4), (a0 as usize, 4)], || {
            let mut sel = [0u32; 8];
            if select_ok(&mut sel) {
                run_blocks(&B_E3880_A, &sel, p.esi as usize, p.esi as usize);
                run_blocks(&B_E3880_B, &sel, a0 as usize, a0 as usize);
            }
        });
    }
}
regs_thunk!(e3880_thunk, e3880_entry);

/// 0x4E3A10: ESI = default float (in place), arg0 = a second float (in place).
extern "C" fn e3a10_entry(r: &mut Pushad, args: *const u32) {
    unsafe {
        let p = *r;
        let a0 = *args;
        shadowed_blend(B_FIRST + 8 + 3, &p, a0, &[(p.esi as usize, 4), (a0 as usize, 4)], || {
            let mut sel = [0u32; 8];
            if select_ok(&mut sel) {
                run_blocks(&B_E3A10_A, &sel, p.esi as usize, p.esi as usize);
                run_blocks(&B_E3A10_B, &sel, a0 as usize, a0 as usize);
            }
        });
    }
}
regs_thunk!(e3a10_thunk, e3a10_entry);

/// 0x4E3230: EAX, EDI and arg0 = three vec3 blended in place.
extern "C" fn e3230_entry(r: &mut Pushad, args: *const u32) {
    unsafe {
        let p = *r;
        let a0 = *args;
        shadowed_blend(B_FIRST + 8 + 1, &p, a0, &[(p.eax as usize, 12), (p.edi as usize, 12), (a0 as usize, 12)], || {
            let mut sel = [0u32; 8];
            if select_ok(&mut sel) {
                run_blocks(&B_E3230_A, &sel, p.eax as usize, p.eax as usize);
                run_blocks(&B_E3230_B, &sel, p.edi as usize, p.edi as usize);
                run_blocks(&B_E3230_C, &sel, a0 as usize, a0 as usize);
            }
        });
    }
}
regs_thunk!(e3230_thunk, e3230_entry);

/// 0x4E2D80: ESI = out (0x38 bytes), EDI = default vec3, arg0 = second default vec3. The tail
/// copies eight globals (the sky-colour lerps and the cloud scroll) in on both paths.
extern "C" fn e2d80_entry(r: &mut Pushad, args: *const u32) {
    unsafe {
        let p = *r;
        let a0 = *args;
        let out = p.esi as usize;
        shadowed_blend(B_FIRST + 8, &p, a0, &[(out, 0x38)], || {
            let mut sel = [0u32; 8];
            if select_ok(&mut sel) {
                run_blocks(&B_E2D80_A, &sel, p.edi as usize, out);
                run_blocks(&B_E2D80_B, &sel, a0 as usize, out);
            } else {
                copy_dwords(out, p.edi as usize, 3);
                copy_dwords(out + 0xC, a0 as usize, 3);
            }
            for (i, g) in [0x00F9_E5F0usize, 0x00F9_E5EC, 0x00F9_E5E8, 0x00F9_E5E4, 0x00F9_E5E0, 0x00F9_E5DC, 0x0252_6E00, 0x0252_6E04]
                .into_iter()
                .enumerate()
            {
                wf(out + 0x18 + 4 * i, lf(g));
            }
        });
    }
}
regs_thunk!(e2d80_thunk, e2d80_entry);

/// Install this module's replacements (called from hooks::install_all).
pub fn install() {
    unsafe {
        let mut done = 0;
        let total = PORTS.len();
        let table: [(usize, &[u8], &[usize], usize); 14] = [
            (SELECT, &SELECT_BODY, &SELECT_BODY_CALLS, select_entry as *const () as usize),
            (UPDATE, &UPDATE_BODY, &UPDATE_BODY_CALLS, weather_update_entry as *const () as usize),
            (B_FIRST, &DF0C0_BODY, &DF0C0_BODY_CALLS, df0c0_thunk as *const () as usize),
            (B_FIRST + 1, &E0470_BODY, &E0470_BODY_CALLS, e0470_thunk as *const () as usize),
            (B_FIRST + 2, &E0CA0_BODY, &E0CA0_BODY_CALLS, e0ca0_thunk as *const () as usize),
            (B_FIRST + 3, &E0D70_BODY, &E0D70_BODY_CALLS, e0d70_thunk as *const () as usize),
            (B_FIRST + 4, &E19E0_BODY, &E19E0_BODY_CALLS, e19e0_thunk as *const () as usize),
            (B_FIRST + 5, &E2380_BODY, &E2380_BODY_CALLS, e2380_thunk as *const () as usize),
            (B_FIRST + 6, &E2860_BODY, &E2860_BODY_CALLS, e2860_thunk as *const () as usize),
            (B_FIRST + 7, &E2AA0_BODY, &E2AA0_BODY_CALLS, e2aa0_thunk as *const () as usize),
            (B_FIRST + 8, &E2D80_BODY, &E2D80_BODY_CALLS, e2d80_thunk as *const () as usize),
            (B_FIRST + 9, &E3230_BODY, &E3230_BODY_CALLS, e3230_thunk as *const () as usize),
            (B_FIRST + 10, &E3880_BODY, &E3880_BODY_CALLS, e3880_thunk as *const () as usize),
            (B_FIRST + 11, &E3A10_BODY, &E3A10_BODY_CALLS, e3a10_thunk as *const () as usize),
        ];
        for (id, body, calls, thunk) in table {
            let port = &PORTS[id];
            // every port but weather_update keeps a relocated original for the shadow window
            if id != UPDATE {
                match detour::relocate(port.addr, body, calls) {
                    Ok(copy) => port.original.store(copy, Ordering::Relaxed),
                    Err(e) => log(&format!("port_weather: {}: no original copy: {e:?}", port.name)),
                }
            }
            if replace_pinned(port.name, port.addr, body, thunk) {
                done += 1;
            }
        }
        log(&format!("port_weather: replaced {done}/{total} with Rust"));
    }
}

/// Per-function call counts for the periodic log.
pub fn summary() -> String {
    let parts: Vec<String> = PORTS
        .iter()
        .filter_map(|p| {
            let c = p.calls.load(Ordering::Relaxed);
            (c > 0).then(|| format!("{} {c} ({})", p.name, p.mismatches.load(Ordering::Relaxed)))
        })
        .collect();
    if parts.is_empty() { String::new() } else { format!("port_weather: {}", parts.join(", ")) }
}

